import {area} from './adapter.mjs';
export const defaultMachine={name:'Bodor P3 12kW — DXF',width:3000,height:1500,margin:12,gap:8,allowRotation:true};
export function validateMachine(m){if([m.width,m.height].some(x=>!Number.isFinite(x)||x<100)||[m.margin,m.gap].some(x=>!Number.isFinite(x)||x<0)||m.margin*2>=Math.min(m.width,m.height))throw Error('מידות לוח, שוליים או רווחים אינם תקינים');}
export function nest(parts,machine){validateMachine(machine);let plates=parts.filter(p=>p.plate),sheets=[],rejected=[];
 for(let p of [...plates].sort((a,b)=>b.plate.width*b.plate.height-a.plate.width*a.plate.height||a.id.localeCompare(b.id))){let a=p.plate;if(p.warnings.length){rejected.push({id:p.id,mark:p.mark,message:p.warnings.join('; ')});continue;}let dims={minX:Math.min(...a.outline.map(v=>v[0])),minY:Math.min(...a.outline.map(v=>v[1])),width:a.width,height:a.height},candidate;
  let find=s=>{for(let [i,r]of s.free.entries())for(let rot of machine.allowRotation?[false,true]:[false]){let w=rot?a.height:a.width,h=rot?a.width:a.height;if(w+machine.gap<=r.w+1e-6&&h+machine.gap<=r.h+1e-6){let score=Math.min(r.w-w-machine.gap,r.h-h-machine.gap)*1e6+Math.max(r.w-w-machine.gap,r.h-h-machine.gap);if(!candidate||score<candidate.score)candidate={sheet:s,rect:r,index:i,rot,w,h,score}}}};
  sheets.filter(s=>s.material===p.material&&s.thickness===a.thickness).forEach(find);
  if(!candidate){let s={id:sheets.length+1,material:p.material,thickness:a.thickness,width:machine.width,height:machine.height,free:[{x:machine.margin,y:machine.margin,w:machine.width-2*machine.margin+machine.gap,h:machine.height-2*machine.margin+machine.gap}],parts:[]};find(s);if(!candidate){rejected.push({id:p.id,mark:p.mark,message:'הפלטה גדולה מהלוח הזמין'});continue;}sheets.push(s);}
  let c=candidate,placed={part:p,...dims,x:c.rect.x,y:c.rect.y,rotated:c.rot,w:c.w,h:c.h},used={x:placed.x,y:placed.y,w:c.w+machine.gap,h:c.h+machine.gap},free=[];
  for(let r of c.sheet.free){if(used.x>=r.x+r.w||used.x+used.w<=r.x||used.y>=r.y+r.h||used.y+used.h<=r.y){free.push(r);continue;}if(used.x>r.x)free.push({x:r.x,y:r.y,w:used.x-r.x,h:r.h});if(used.x+used.w<r.x+r.w)free.push({x:used.x+used.w,y:r.y,w:r.x+r.w-used.x-used.w,h:r.h});if(used.y>r.y)free.push({x:r.x,y:r.y,w:r.w,h:used.y-r.y});if(used.y+used.h<r.y+r.h)free.push({x:r.x,y:used.y+used.h,w:r.w,h:r.y+r.h-used.y-used.h});}
  c.sheet.free=free.filter((r,i)=>r.w>1e-6&&r.h>1e-6&&!free.some((q,j)=>j!==i&&q.x<=r.x+1e-6&&q.y<=r.y+1e-6&&q.x+q.w>=r.x+r.w-1e-6&&q.y+q.h>=r.y+r.h-1e-6&&(j<i||q.w*q.h>r.w*r.h+1e-6)));c.sheet.parts.push(placed);
 }
 const result={sheets,rejected,total:plates.length,placed:sheets.reduce((n,s)=>n+s.parts.length,0),area:plates.filter(p=>!rejected.some(r=>r.id===p.id)).reduce((s,p)=>s+area(p.plate.outline),0)};result.utilization=result.area/(sheets.length*machine.width*machine.height||1);validateNesting(result,machine);return result;
}
export function mapped(item,p){let x=p[0]-item.minX,y=p[1]-item.minY;return item.rotated?[item.x+y,item.y+item.width-x]:[item.x+x,item.y+y];}
export function validateNesting(result,m){let ids=new Set;for(let s of result.sheets){for(let a of s.parts){if(ids.has(a.part.id))throw Error('חלק כפול בקינון');ids.add(a.part.id);if(a.x<m.margin-.001||a.y<m.margin-.001||a.x+a.w>s.width-m.margin+.001||a.y+a.h>s.height-m.margin+.001)throw Error('חלק חורג מהלוח');if(a.part.material!==s.material||a.part.plate.thickness!==s.thickness)throw Error('חומרים או עוביים עורבבו');}for(let i=0;i<s.parts.length;i++)for(let j=i+1;j<s.parts.length;j++){let a=s.parts[i],b=s.parts[j];if(!(a.x+a.w+m.gap<=b.x+.001||b.x+b.w+m.gap<=a.x+.001||a.y+a.h+m.gap<=b.y+.001||b.y+b.h+m.gap<=a.y+.001))throw Error('פלטות חופפות או ללא המרווח הנדרש');}}if(ids.size+result.rejected.length!==result.total)throw Error('מספר הפלטות אינו תואם למקור');return true;}
